import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        pkgs = {}
        for fw in proj.get('frameworks', []):
            for p in fw.get('topLevelPackages', []):
                pkgs[p['id']] = {'requested': p.get('requestedVersion',''), 'resolved': p.get('resolvedVersion','')}
        result[name] = pkgs
    return result

b = extract(baseline)
a = extract(after)

print('=== CHANGES ===')
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(proj, {})
    ap = a.get(proj, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg, {}).get('resolved', '')
        av = ap.get(pkg, {}).get('resolved', '')
        br = bp.get(pkg, {}).get('requested', '')
        ar = ap.get(pkg, {}).get('requested', '')
        if bv != av or br != ar:
            print(f'{proj} | {pkg} | {br} -> {ar} (resolved: {bv} -> {av})')

print()
print('=== UNCHANGED ===')
for proj in sorted(set(list(b.keys()) + list(a.keys()))):
